// Step 3: buffered playback of OTHER players' confirmed movement.
//
// Frames are generated by the REAL Ruby engine (the same generator the
// prediction tests use), so every assertion about "what the remote snake did"
// is checked against server output rather than against an expectation written
// by hand here.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { RemotePlayback, PLAYBACK_TUNING } from '../public/multiplayer/playback.js';

const trace = JSON.parse(readFileSync(new URL('./fixtures/prediction-trace.json', import.meta.url), 'utf8'));
const CFG = trace.config;
const TICK = CFG.tick_ms;
const scenario = (name) => {
  const found = trace.scenarios.find((entry) => entry.name === name);
  assert.ok(found, `missing scenario ${name}`);
  return structuredClone(found);
};

function playbackFor(scenario, { limits = {}, tickMs = TICK } = {}) {
  const pb = new RemotePlayback({
    tickMs, columns: scenario.frames[0].b.c, rows: scenario.frames[0].b.r, limits,
    clock: () => 0
  });
  pb.enable('responsive');
  return pb;
}

// Delivers frames at a schedule, sampling the playhead as a browser would.
function runPlayback(scenario, { oneWayMs = 0, jitter = [], limits = {}, sampleEveryMs = 8 } = {}) {
  let time = 0;
  const pb = new RemotePlayback({
    tickMs: TICK, columns: scenario.frames[0].b.c, rows: scenario.frames[0].b.r,
    limits, clock: () => time
  });
  pb.enable('responsive');
  const schedule = scenario.frames.map((frame, index) => ({
    frame, at: frame.t * TICK + oneWayMs + (jitter.length ? jitter[index % jitter.length] : 0)
  }));
  const samples = [];
  const lastAt = schedule.length ? Math.max(...schedule.map((entry) => entry.at)) : 0;
  let next = 0;
  let maxDelay = 0;
  let minDelay = Infinity;
  while (time <= lastAt + 6 * TICK) {
    while (next < schedule.length && schedule[next].at <= time) {
      pb.pushSnapshot(schedule[next].frame, time);
      next += 1;
    }
    const sample = pb.sample(time);
    if (sample) {
      samples.push({ at: time, ...sample });
      maxDelay = Math.max(maxDelay, sample.delayMs);
      minDelay = Math.min(minDelay, sample.delayMs);
    }
    time += sampleEveryMs;
  }
  return { pb, samples, maxDelay, minDelay };
}

// The exact cell each remote snake occupies at a confirmed tick.
const confirmedBody = (scenario, tick, playerId = 2) => {
  const frame = scenario.frames.find((entry) => entry.t === tick);
  if (!frame) return null;
  const player = frame.p.find((entry) => entry.i === playerId);
  return player ? player.b : null;
};

test('playback stores confirmed frames in tick order and rejects out-of-order ones', () => {
  const s = scenario('turns');
  const pb = playbackFor(s);
  pb.pushSnapshot(s.frames[3], 0);
  pb.pushSnapshot(s.frames[5], 10);
  pb.pushSnapshot(s.frames[4], 20); // late arrival, lower tick
  const summary = pb.summary();
  assert.equal(summary.outOfOrder, 1, 'a lower tick is refused, never inserted out of order');
  assert.deepEqual(pb.frames.map((frame) => frame.tick), [3, 5]);
  // ...and a duplicate tick is recognised rather than replayed as movement.
  pb.pushSnapshot(s.frames[5], 30);
  assert.equal(pb.summary().duplicates, 1);
  assert.equal(pb.frames.length, 2);
});

test('the playhead runs behind the live edge by the buffer delay, never ahead of it', () => {
  const s = scenario('wrap');
  const { samples } = runPlayback(s, { oneWayMs: 120 });
  assert.ok(samples.length > 50);
  for (const sample of samples) {
    assert.ok(sample.tick <= sample.nextTick - 1 || sample.nextTick === null,
      'the playhead never samples beyond the confirmed edge');
    assert.ok(sample.bufferedTicks >= 0);
  }
  // It also does not sit at the live edge: that lag is the whole point.
  const settled = samples.filter((sample) => sample.buffered >= 4);
  assert.ok(settled.some((sample) => sample.bufferedTicks >= 1),
    'settled playback must lag the newest confirmed tick');
});

test('remote interpolation walks the confirmed path: every segment moves at most one cell', () => {
  const s = scenario('turns');
  const pb = playbackFor(s);
  s.frames.forEach((frame, index) => pb.pushSnapshot(frame, index * TICK));
  for (let index = 0; index < pb.frames.length - 1; index += 1) {
    const older = pb.frames[index];
    const newer = pb.frames[index + 1];
    const blended = pb.blend(older, newer, 0.5);
    for (const [id, player] of blended) {
      for (const segment of player.smooth) {
        if (!segment.smooth) continue;
        const dx = Math.abs(segment.x - (segment.from % pb.columns));
        const dy = Math.abs(segment.y - Math.floor(segment.from / pb.columns));
        // Half a tick of movement: exactly 0.5 cells on one axis. Never a
        // diagonal shortcut and never a jump across the board.
        assert.ok(dx + dy <= 0.5001 + 1e-9, `segment of player ${id} moved ${dx + dy} cells in half a tick`);
        assert.ok(dx <= 0.5 + 1e-9 && dy <= 0.5 + 1e-9, 'no diagonal interpolation');
      }
    }
  }
});

test('a turn is played as the turn it was, not as a diagonal cut', () => {
  const s = scenario('turns');
  // Tick 2 is the first tick where the head has turned down (engine-generated).
  const pb = playbackFor(s);
  s.frames.forEach((frame, index) => pb.pushSnapshot(frame, index * TICK));
  const index = pb.frames.findIndex((frame) => frame.tick === 2);
  assert.ok(index > 0, 'the fixture must contain the turning tick');
  const older = pb.frames[index - 1];
  const newer = pb.frames[index];
  const before = older.players.get(1).cells[0];
  const after = newer.players.get(1).cells[0];
  assert.notEqual(before, after, 'the head really did move');
  const blended = pb.blend(older, newer, 1);
  const head = blended.get(1).smooth[0];
  // At alpha 1 the interpolated head is EXACTLY the confirmed cell: playback
  // never overshoots a confirmed position to "smooth out" a corner.
  assert.equal(Math.round(head.x) + Math.round(head.y) * pb.columns, after);
  assert.equal(head.wraps, false);
});

test('a wrapped move is animated around the edge, never across the board', () => {
  const s = scenario('wrap');
  const columns = s.frames[0].b.c;
  const pb = playbackFor(s);
  s.frames.forEach((frame, index) => pb.pushSnapshot(frame, index * TICK));
  let wrapped = 0;
  for (let index = 0; index < pb.frames.length - 1; index += 1) {
    const older = pb.frames[index];
    const newer = pb.frames[index + 1];
    for (const [id, player] of pb.blend(older, newer, 0.5)) {
      for (const segment of player.smooth) {
        if (!segment.smooth) continue;
        const fromX = segment.from % columns;
        const toX = segment.cell % columns;
        if (Math.abs(toX - fromX) <= 1) continue;
        // This segment wrapped. Its continuous x must be within one cell of the
        // edge it left, not halfway across the board.
        wrapped += 1;
        assert.ok(segment.wraps, 'a wrapped step must be flagged');
        assert.ok(segment.x <= -0.49 || segment.x >= columns - 0.51,
          `wrapped segment rendered at x=${segment.x}, which is a cross-board flight`);
      }
    }
  }
  assert.ok(wrapped > 0, 'fixture must actually wrap a snake');
});

test('wrapping vertically is handled the same way', () => {
  const pb = new RemotePlayback({ tickMs: 100, columns: 10, rows: 6, clock: () => 0 });
  pb.enable('responsive');
  const body = (head) => ({ v: 1, type: 'snapshot', m: 1, s: 'running', t: 0, b: { c: 10, r: 6 },
    f: [], p: [{ i: 1, n: 'A', c: '#00FF00', b: [head, head - 10, head - 20], l: 3, a: true, d: 'down', sc: 0 }] });
  pb.pushSnapshot(body(55), 0); // bottom row, row 5
  pb.pushSnapshot({ ...body(5), t: 1 }, 100); // wrapped to row 0, same column
  const blended = pb.blend(pb.frames[0], pb.frames[1], 0.5);
  const head = blended.get(1).smooth[0];
  assert.ok(head.wraps, 'vertical wrap flagged');
  assert.ok(head.y <= -0.49 || head.y >= 5.49, `wrapped vertically to y=${head.y}`);
});

test('playback never fabricates movement when confirmed history runs out', () => {
  const s = scenario('idle');
  const pb = playbackFor(s);
  pb.pushSnapshot(s.frames[0], 0);
  pb.pushSnapshot(s.frames[1], TICK);
  const newest = s.frames[1];
  // Go quiet: no more frames for two seconds.
  let time = TICK;
  let sample = null;
  for (let index = 0; index < 250; index += 1) {
    time += 8;
    sample = pb.sample(time);
  }
  assert.ok(sample.atLiveEdge, 'playback stops at the newest confirmed state');
  assert.equal(sample.tick, newest.t, 'the playhead is clamped to confirmed history');
  assert.ok(pb.summary().underruns > 0, 'underruns are counted, not hidden');
  assert.equal(sample.interpolated, false, 'no interpolation without a next confirmed tick');
  // ...and the body drawn is exactly the last confirmed body.
  const drawn = [...sample.players.get(1).cells];
  assert.deepEqual(drawn, newest.p.find((player) => player.i === 1).b);
});

test('the playback buffer is bounded in both memory and latency', () => {
  const s = scenario('wrap');
  const pb = playbackFor(s, { limits: { maxBufferTicks: 6 } });
  s.frames.forEach((frame, index) => pb.pushSnapshot(frame, index * TICK));
  assert.ok(pb.frames.length <= 6, `buffer kept ${pb.frames.length} ticks`);
  const summary = pb.summary();
  assert.ok(summary.dropped > 0, 'old ticks are discarded rather than accumulated');
  assert.ok(summary.delayMs <= pb.limits.maxDelayMs);
  assert.ok(summary.delayMs >= pb.limits.minDelayMs);
});

test('adaptive delay stays inside its bounds, moves gradually and tracks jitter', () => {
  const stable = scenario('turns');
  const calm = runPlayback(stable, { oneWayMs: 40 });
  assert.ok(calm.maxDelay <= PLAYBACK_TUNING.maxDelayMs);
  assert.ok(calm.minDelay >= PLAYBACK_TUNING.minDelayMs);
  // A clean link should not wander far from the stable target.
  assert.ok(calm.maxDelay - calm.minDelay <= 220,
    `delay oscillated by ${calm.maxDelay - calm.minDelay}ms on a stable link`);

  const bursty = runPlayback(stable, { oneWayMs: 120, jitter: [0, 260, 40, 320, 0, 180, 0, 240] });
  assert.ok(bursty.pb.summary().jitterMs > 0, 'bursty delivery must be measured as jitter');
  assert.ok(bursty.maxDelay <= PLAYBACK_TUNING.maxDelayMs);
  // Gradual: no single sample may jump the delay by a large amount.
  const deltas = [];
  for (let index = 1; index < bursty.samples.length; index += 1) {
    deltas.push(Math.abs(bursty.samples[index].delayMs - bursty.samples[index - 1].delayMs));
  }
  assert.ok(Math.max(...deltas) <= 120, `delay jumped ${Math.max(...deltas)}ms in one sample`);
});

test('missing confirmed ticks hold the board instead of inventing a route', () => {
  const s = scenario('turns');
  const pb = playbackFor(s);
  pb.pushSnapshot(s.frames[0], 0);
  pb.pushSnapshot(s.frames[1], TICK);
  // Skip tick 2 entirely: the head's next confirmed position is tick 3.
  pb.pushSnapshot(s.frames[3], 3 * TICK);
  assert.equal(pb.summary().gaps, 1);
  assert.equal(pb.summary().missingTicks, 1);
  let time = 3 * TICK;
  let sample = null;
  for (let index = 0; index < 40; index += 1) { time += 8; sample = pb.sample(time); }
  // Between tick 1 and tick 3 there is no adjacent pair, so nothing is drawn as
  // motion; the board holds a real confirmed body.
  assert.equal(sample.interpolated, false);
  const drawn = [...sample.players.get(1).cells];
  const validBodies = [s.frames[1], s.frames[3]].map((frame) => frame.p.find((p) => p.i === 1).b);
  assert.ok(validBodies.some((body) => JSON.stringify(body) === JSON.stringify(drawn)),
    'the displayed body is always one the server actually confirmed');
});

test('a large gap asks for an authoritative resync, and a request is dequeued once', () => {
  const s = scenario('turns');
  const pb = playbackFor(s, { limits: { resyncGapTicks: 4 } });
  pb.pushSnapshot(s.frames[0], 0);
  pb.pushSnapshot(s.frames[9], TICK); // 9 ticks missing
  assert.ok(pb.summary().resyncs >= 1);
  const reason = pb.takeResyncRequest();
  assert.match(String(reason), /gap/);
  assert.equal(pb.takeResyncRequest(), false, 'one gap produces one request, not a flood');
});

test('compact movement frames rebuild the exact confirmed bodies', () => {
  const s = scenario('turns');
  // Turn full snapshots into the compact frames the server would broadcast,
  // using the same head/length/scalars the Ruby encoder emits.
  const movements = s.frames.map((frame) => ({
    v: 1, type: 'movement', m: frame.m, s: frame.s, t: frame.t, ts: frame.ts, f: frame.f,
    p: frame.p.map((player) => ({
      i: player.i, h: player.b[0], d: player.d, l: player.l, sc: player.sc,
      a: player.a, fr: player.fr, cy: player.cy, is: player.is, it: player.it
    }))
  }));

  const pb = playbackFor(s);
  pb.pushSnapshot(s.frames[0], 0); // the subscription seed
  for (const movement of movements.slice(1)) pb.pushMovement(movement, movement.t * TICK);

  assert.equal(pb.summary().reconstructed, (movements.length - 1) * s.frames[0].p.length);
  assert.equal(pb.summary().reconstructRejects, 0);
  for (const frame of s.frames) {
    const stored = pb.byTick.get(frame.t);
    assert.ok(stored, `tick ${frame.t} was dropped`);
    for (const player of frame.p) {
      assert.deepEqual(stored.players.get(player.i).cells, player.b,
        `rebuilt body for player ${player.i} at tick ${frame.t} must equal the server's`);
    }
  }
});

test('a movement frame without a usable predecessor is refused and resyncs', () => {
  const s = scenario('turns');
  const pb = playbackFor(s);
  // No snapshot yet: nothing to rebuild from.
  const accepted = pb.pushMovement({
    v: 1, type: 'movement', m: s.frames[0].m, t: 5, p: [{ i: 1, h: 10, l: 3, d: 'right' }]
  }, 0);
  assert.equal(accepted, false);
  assert.ok(pb.summary().resyncs >= 1);

  pb.pushSnapshot(s.frames[0], TICK);
  // A length that cannot follow the previous body (a tick can add at most one
  // cell) is refused rather than rendered as a wrong snake.
  const bad = pb.pushMovement({
    v: 1, type: 'movement', m: s.frames[0].m, t: 1, p: [{ i: 1, h: 11, l: 40, d: 'right' }]
  }, 2 * TICK);
  assert.equal(bad, false);
  assert.equal(pb.summary().reconstructRejects, 1);
});

test('freeze, elimination and match end are respected without ever animating through them', () => {
  const freeze = scenario('freeze');
  const pb = playbackFor(freeze);
  freeze.frames.forEach((frame, index) => pb.pushSnapshot(frame, index * TICK));
  const frozenTicks = freeze.frames.filter((frame) => frame.p[0].fr).map((frame) => frame.t);
  assert.ok(frozenTicks.length >= 2);
  // A frozen snake's confirmed cells do not change, so interpolation is a hold.
  for (const tick of frozenTicks.slice(1)) {
    const newer = pb.byTick.get(tick);
    const older = pb.byTick.get(tick - 1);
    if (!newer || !older) continue;
    const head = pb.blend(older, newer, 0.5).get(1).smooth[0];
    const fromX = head.from % pb.columns;
    const fromY = Math.floor(head.from / pb.columns);
    assert.ok(Math.abs(head.x - fromX) <= 0.51 && Math.abs(head.y - fromY) <= 0.51,
      'a frozen snake does not drift');
  }

  const dead = scenario('eliminated');
  const pb2 = playbackFor(dead);
  dead.frames.forEach((frame, index) => pb2.pushSnapshot(frame, index * TICK));
  const final = dead.frames.at(-1);
  const stored = pb2.byTick.get(final.t);
  assert.equal(stored.players.get(1).alive, false, 'the elimination is stored from the server');
  assert.deepEqual(stored.players.get(1).cells, final.p.find((player) => player.i === 1).b);
});

test('two independent clients can each track their own snake from the same frames', () => {
  const s = scenario('turns');
  const a = playbackFor(s);
  const b = playbackFor(s);
  s.frames.forEach((frame, index) => { a.pushSnapshot(frame, index * TICK); b.pushSnapshot(frame, index * TICK); });
  for (const tick of [3, 6, 9]) {
    const frame = s.frames.find((entry) => entry.t === tick);
    for (const client of [a, b]) {
      const stored = client.byTick.get(tick);
      for (const player of frame.p) {
        assert.deepEqual(stored.players.get(player.i).cells, player.b);
      }
    }
  }
  // Independent state: resetting one must not disturb the other.
  a.reset('test');
  assert.equal(a.frames.length, 0);
  assert.ok(b.frames.length > 0);
});

test('classic Brawl is completely inert: no buffer, no delay, no samples', () => {
  const s = scenario('turns');
  const pb = new RemotePlayback({ tickMs: TICK, clock: () => 0 });
  assert.equal(pb.enabled, false);
  assert.equal(pb.pushSnapshot(s.frames[0], 0), false);
  assert.equal(pb.pushMovement(s.frames[1], 0), false);
  assert.equal(pb.sample(0), null);
  assert.equal(pb.summary().frames, 0);
});

test('the shipped tuning targets match the documented bands', () => {
  assert.ok(PLAYBACK_TUNING.stableDelayMs >= 100 && PLAYBACK_TUNING.stableDelayMs <= 200);
  assert.ok(PLAYBACK_TUNING.moderateDelayMs >= 200 && PLAYBACK_TUNING.moderateDelayMs <= 350);
  assert.ok(PLAYBACK_TUNING.heavyDelayMs >= 350 && PLAYBACK_TUNING.heavyDelayMs <= 600);
  assert.ok(PLAYBACK_TUNING.minDelayMs < PLAYBACK_TUNING.stableDelayMs);
  assert.ok(PLAYBACK_TUNING.maxDelayMs >= PLAYBACK_TUNING.heavyDelayMs);
  // Bounds that keep the board and the memory sane.
  assert.ok(PLAYBACK_TUNING.maxBufferTicks <= 60);
  assert.ok(PLAYBACK_TUNING.maxLagTicks <= PLAYBACK_TUNING.maxBufferTicks);
});
